import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {gunzipSync} from 'node:zlib';
const home=import.meta.dir, source=home+'/../barrel-native-catalog-ranker-fit-20261118';
const sha=(v:any)=>createHash('sha256').update(v).digest('hex');
const reg=JSON.parse(readFileSync(home+'/registration.json','utf8'));
for(const f of reg.inputs)assert.equal(sha(readFileSync(source+'/'+f.path)),f.sha256);
const m=JSON.parse(readFileSync(source+'/validation-selected-model.json','utf8'));
assert.equal(m.mean.length,191);
const pack=(a:number[])=>{const b=Buffer.alloc(a.length*8);a.forEach((v,i)=>{assert.ok(Number.isFinite(v));b.writeDoubleBE(v===0?0:v,i*8);});return b.toString('hex');};
const complete=(vectors:string[],r:any)=>{
 const first=Buffer.alloc(4),last=Buffer.alloc(13);first.writeUInt32BE(vectors.length);
 [r.cleanupIndex,r.beforeIndex,r.outsideIndex].forEach((v,i)=>last.writeUInt32BE(v,i*4));last[12]=Number(r.allowInference);
 return sha(Buffer.concat([first,...vectors.map(s=>Buffer.from(s,'hex')),Buffer.from(r.valid.map(Number)),last]));
};
type Bucket={targets:Map<number,number>,raw:Set<string>};
const add=(groups:Map<string,Bucket>,key:string,raw:string,target:number)=>{let b=groups.get(key);if(!b){b={targets:new Map(),raw:new Set()};groups.set(key,b);}b.targets.set(target,(b.targets.get(target)||0)+1);b.raw.add(raw);};
const summary=(g:Map<string,Bucket>)=>({distinctOrderedInputs:g.size,contradictoryOrderedInputs:[...g.values()].filter(x=>x.targets.size>1).length,contradictoryGroupsWithDistinctRawInputs:[...g.values()].filter(x=>x.targets.size>1&&x.raw.size>1).length,maxObservedCorrect:[...g.values()].reduce((s,b)=>s+Math.max(...b.targets.values()),0)});
const countsOf=(keys:string[],valid:boolean[])=>{const c=new Map<string,number>();keys.forEach((s,i)=>{if(valid[i])c.set(s,(c.get(s)||0)+1);});return c;};
const allRaw=new Map<string,Bucket>(), allNorm=new Map<string,Bucket>();const folds:any={};
for(const fold of ['train','validation']){
 const counts:any={};const plus=(k:string,n:number)=>{counts[k]=(counts[k]||0)+n;};
 const rawGroups=new Map<string,Bucket>(), normGroups=new Map<string,Bucket>();
 const clipped=Array(191).fill(0),validClipped=Array(191).fill(0);
 const lines=gunzipSync(readFileSync(source+'/data/'+fold+'.jsonl.gz')).toString('utf8').trim().split('\n');
 assert.equal(lines.length,fold==='train'?5388:1587);
 for(const line of lines){
  const r=JSON.parse(line);assert.equal(r.fold,fold);plus('records',1);
  const rawKeys:string[]=[],normKeys:string[]=[];let ood=false,rowClip=false;
  r.features.forEach((x:number[],j:number)=>{
   assert.equal(x.length,191);
   const z=x.map((v,i)=>{const n=(v-m.mean[i])/m.scale[i];const clip=Math.abs(n)>8;if(clip){clipped[i]++;validClipped[i]+=Number(r.valid[j]);plus('clippedCoordinates',1);rowClip=true;}if(clip||m.constant[i]&&Math.abs(v-m.mean[i])>1e-8)ood=true;return Math.min(8,Math.max(-8,n));});
   rawKeys.push(pack(x));normKeys.push(pack(z));plus('options',1);plus('validOptions',Number(r.valid[j]));
  });
  plus('rowsWithClipping',Number(rowClip));plus('oodRows',Number(ood));
  const rawCounts=countsOf(rawKeys,r.valid),normCounts=countsOf(normKeys,r.valid),target=r.targetIndex;assert.ok(r.valid[target]);
  const a=rawCounts.get(rawKeys[target])!,b=normCounts.get(normKeys[target])!;
  plus('rawTargetAliased',Number(a>1));plus('normalizedTargetAliased',Number(b>1));plus('targetGainsRivalsAfterNormalization',Number(b>a));plus('admissibleTargetGainsRivalsAfterNormalization',Number(b>a&&r.allowInference&&!ood));
  const aliases=new Map<string,Set<string>>();normKeys.forEach((key,i)=>{if(r.valid[i]){if(!aliases.has(key))aliases.set(key,new Set());aliases.get(key)!.add(rawKeys[i]);}});
  plus('normalizedGroupsMergingDistinctValidRawVectors',[...aliases.values()].filter(x=>x.size>1).length);
  const alternative=target!==r.cleanupIndex&&target!==r.outsideIndex;
  plus('uniqueCompleteAlternativeTargetsBeforeOod',Number(alternative&&b===1&&r.allowInference));plus('uniqueCompleteAlternativeTargetsAfterOod',Number(alternative&&b===1&&r.allowInference&&!ood));
  const raw=complete(rawKeys,r),normal=complete(normKeys,r);add(rawGroups,raw,raw,target);add(normGroups,normal,raw,target);add(allRaw,raw,raw,target);add(allNorm,normal,raw,target);
 }
 folds[fold]={counts,rawOrderedInputGroups:summary(rawGroups),normalizedOrderedInputGroups:summary(normGroups),clippedCoordinatesByFeature:clipped,validClippedCoordinatesByFeature:validClipped};
}
const original=JSON.parse(readFileSync(home+'/result.json','utf8'));
assert.deepEqual(folds,original.folds);assert.deepEqual({rawOrderedInputGroups:summary(allRaw),normalizedOrderedInputGroups:summary(allNorm)},original.combined);
const result={passed:true,registrationSha256:sha(readFileSync(home+'/registration.json')),records:6975,featureCount:191,allIntegerCountsAndFeatureClipVectorsExact:true,normalizedBinary64InputGroupingIndependentlyReconstructed:true,testParsed:false,modelRefitted:false,servingPolicyChanged:false};
writeFileSync(home+'/independent-verification.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(result));
